      "code": "outcomes = {}\ndef apply(key):\n    if key not in outcomes: outcomes[key] = \"accepted\"\n    return outcomes[key]\nprint(apply(\"synthetic-op\"))\nprint(apply(\"synthetic-op\"))\nprint(len(outcomes))",
